<?php require_once __DIR__ . '/../../includes/layout.php'; require_role(['Teacher','Admin']); check_csrf(); if($_SERVER['REQUEST_METHOD']==='POST'){db()->prepare('INSERT INTO announcements(title,body,target_role,created_by) VALUES(?,?,?,?)')->execute([$_POST['title'],$_POST['body'],$_POST['target_role'],$_SESSION['user_id']]); set_flash('success','Announcement posted.'); redirect('announcements.php');} render_header('Teacher Announcements'); ?><div class="page-title"><div><h1>Announcements</h1><p>Create and view announcements.</p></div></div><div class="row g-4"><div class="col-lg-4"><div class="panel"><form method="post"><?= csrf_field() ?><div class="mb-3"><label>Title</label><input name="title" class="form-control" required></div><div class="mb-3"><label>Body</label><textarea name="body" class="form-control" required></textarea></div><div class="mb-3"><label>Target</label><select name="target_role" class="form-select"><option>All</option><option>Student</option><option>Parent</option><option>Teacher</option></select></div><button class="btn btn-primary w-100">Post</button></form></div></div><div class="col-lg-8"><div class="panel"><?php foreach(rows('SELECT a.*,u.full_name FROM announcements a LEFT JOIN users u ON u.id=a.created_by ORDER BY a.created_at DESC') as $a): ?><div class="border-bottom py-3"><strong><?= e($a['title']) ?></strong> <span class="badge bg-primary"><?= e($a['target_role']) ?></span><p><?= e($a['body']) ?></p><small class="text-muted">By <?= e($a['full_name']??'System') ?> • <?= e($a['created_at']) ?></small></div><?php endforeach; ?></div></div></div><?php render_footer(); ?>
